        public void updateAlarms()
        {
            conSql.open(ConnectionStringAlarm);
            foreach (Allarme allarme in allarmiList)
            {
                allarme.ba.updateAlarmText(conSql);
            }
            
            conSql.close();
        }

        public void destroy()
        {
            try
            {
                //_checkAlarms.Abort();
                canctokenSource.Cancel();
            }
            catch
            {
            }
        }

        #endregion

        #region Private

        private void checkAllarmi(SQLServerConnection _conSql,string plcName)
        {
            bool sended = false;
            foreach (Allarme allarme in allarmiList)
            {
                if (allarme.ba.PLC_NAME == plcName)
                {
                    allarme.checkAllarme(_conSql);
                    if (allarme.ba.NEW_ALM)
                    {
                        if (Core.MyApp.MyApplicationSettings.EnableSoundAlarm)
                            //Core.Communication.tagsList.PC_NEW_ALARM.VALUE = true;

                        if (!sended)
                        {
                            sended = true;
                            NewAlarmSound?.Invoke(this, new EventArgs());
                        }
                        allarme.ba.NEW_ALM = false;
                    }
                }
            }

           
        }

        private void run()
        {
           
            //Attendi 5 minuti dopo l avvio dell applicazione
            int cnt = 0;
            if (!System.Diagnostics.Debugger.IsAttached)
            {
                while (cnt < 10)
                {
                    try
                    {
                        Thread.Sleep(1000);
                        cnt++;
                    }
                    catch (ThreadAbortException)
                    {
                        return;
                    }
                }
            }
            if (conSql == null)
            {
                conSql = new SQLServerConnection();
                conSql.open(ConnectionStringAlarm);
            }
            else
            {
                conSql.open(ConnectionStringAlarm);
            }
            while (_as.IS_RUNNING & !canctokenSource.IsCancellationRequested)
            {
                try
                {
                    //Thread.Sleep(50);
                    Task.Delay(500).Wait();

                    conSql.open(ConnectionStringAlarm);
                    if (conSql.IS_CONNECTED)
                    {
                        //if (!System.Diagnostics.Debugger.IsAttached)
                        //{
                        for (int i = 0; i < plcWatchDog.PLC_STATE.Count; i++)
                        {
                            if (plcWatchDog.PLC_STATE[i].CommState)
                            {
                                if (canControl[i])
                                {
                                    allarmiListPLC[i].checkAlarm(!plcWatchDog.PLC_STATE[i].CommState, conSql);
                                    checkAllarmi(conSql, plc[i].NAME);
                                }
                            else
                            {
                                if (counterControl[i] >= 100)// Inibizione allarmi 
                                {
                                    canControl[i] = true;
                                    counterControl[i] = 1;

                                }
                                else
                                {
                                    counterControl[i]++;
                                }
                            }
                            }
                            else
                            {
                                if (counterNoCom[i] >= 300)
                                {
                                    canControl[i] = false;
                                    counterControl[i] = 1;
                                    counterNoCom[i] = 0;
                                    allarmiListPLC[i].checkAlarm(!plcWatchDog.PLC_STATE[i].CommState, conSql);
                                }
                                else
                                {
                                    counterNoCom[i]++;

                                }
                            }
                        }
                        
                        conSql.close();
                    }
                    //Thread.Sleep(100);
                    
                }
                catch (OperationCanceledException)
                {
                    try
                    {
                        conSql.close();
                    }
                    catch
                    {
                    }
                    return;
                }
                catch (ThreadAbortException)
                {
                    try
                    {
                        conSql.close();
                    }
                    catch
                    {
                    }
                    return;
                }
                catch (Exception ere)
                {
                    //eel.writeToLog("ERRORE", ere.Message, "ThrdAllarmi", DateTime.Now);
                    //_logger.LogError(MethodBase.GetCurrentMethod().DeclaringType.Name + "." + MethodBase.GetCurrentMethod().Name, ex, ex.Message, new object[0]);

                    if (conSql == null)
                    {
                        conSql = new SQLServerConnection();
                        conSql.open(ConnectionStringAlarm);
                    }
                    else if (!conSql.IS_CONNECTED)
                    {
                        conSql.open(ConnectionStringAlarm);
                    }
                }
            }
        }

        #endregion

